Study Data
The analysis uses the Theoph dataset included in R, which contains concentration-time data from 12 subjects who each received a single oral dose of theophylline. Each subject provided 11 blood samples over approximately 24 hours. Sampling times in the dataset are actual times and differ slightly between subjects; for summaries by time point, each sample was assigned its nominal time (0, 0.25, 0.5, 1, 2, 3.5, 5, 7, 9, 12, and 24 hours).


Show Code
nominal_times &lt;- c(0, 0.25, 0.5, 1, 2, 3.5, 5, 7, 9, 12, 24)

pk_data &lt;- Theoph |&gt;
  as_tibble() |&gt;
  rename(ID = Subject, TIME = Time, CONC = conc, DOSE = Dose, WT = Wt) |&gt;
  mutate(
    ID = factor(as.character(ID), levels = as.character(1:12)),
    DOSE_mg = DOSE * WT
  ) |&gt;
  arrange(ID, TIME) |&gt;
  group_by(ID) |&gt;
  mutate(NTIME = nominal_times[row_number()]) |&gt;
  ungroup()

# Observations after dosing; the pre-dose sample is excluded from model fitting
fit_data &lt;- pk_data |&gt; filter(TIME &gt; 0)

n_subjects &lt;- n_distinct(pk_data$ID)
predose &lt;- pk_data |&gt; filter(TIME == 0, CONC &gt; 0)

Individual Two-Compartment Model


Show Code
fit_two_comp &lt;- function(data) {
  dose &lt;- data$DOSE_mg[1]
  model_data &lt;- filter(data, TIME &gt; 0)

  starts &lt;- expand_grid(
    lKa = log(c(0.7, 1.5, 3)),
    lK10 = log(0.1),
    lK12 = log(c(0.1, 0.5, 1.5)),
    lK21 = log(c(0.3, 1.5)),
    lVc = log(c(15, 25))
  ) |&gt;
    pmap(list)

  fit &lt;- fit_multistart(
    CONC ~ two_comp_micro(TIME, exp(lKa), exp(lK10), exp(lK12), exp(lK21), exp(lVc), dose),
    model_data, starts
  )

  params &lt;- if (is.null(fit)) {
    tibble(Ka = NA_real_, K10 = NA_real_, K12 = NA_real_, K21 = NA_real_, Vc = NA_real_, Max_SE_log = NA_real_)
  } else {
    est &lt;- exp(coef(fit))
    tibble(
      Ka = est[["lKa"]], K10 = est[["lK10"]], K12 = est[["lK12"]], K21 = est[["lK21"]], Vc = est[["lVc"]],
      Max_SE_log = tryCatch(max(summary(fit)$coefficients[, "Std. Error"]), error = \(e) Inf)
    )
  }

  bind_cols(params, fit_stats(fit, model_data))
}

two_comp_results &lt;- pk_data |&gt;
  group_by(ID) |&gt;
  group_modify(\(d, k) fit_two_comp(d)) |&gt;
  ungroup() |&gt;
  mutate(
    Vp = Vc * K12 / K21,
    Vss = Vc + Vp,
    CL_F = K10 * Vc,
    sum_k = K10 + K12 + K21,
    beta = (sum_k - sqrt(sum_k^2 - 4 * K10 * K21)) / 2,
    Half_life_beta = log(2) / beta
  )



Two-Compartment Model Results
Out of 36 sets of starting values per subject, the two-compartment model converged for 1 of 12 subjects and failed (false or singular convergence from every start) for 11. Of the converged fits, 1 had at least one parameter with a standard error above 1 on the log scale (roughly a CV above 100%), meaning the parameters are not well identified even where the optimizer converged.


Show Code
two_comp_cols &lt;- c("Ka", "K10", "K12", "K21", "Vc", "R2", "RMSE")

if (n_converged_2c &gt; 0) {
  valid_2c |&gt;
    select(ID, all_of(two_comp_cols), Max_SE_log) |&gt;
    gt() |&gt;
    tab_header(
      title = "Table 5. Two-Compartment Model Parameter Estimates",
      subtitle = sprintf("Subjects with a converged fit (%d of 12)", n_converged_2c)
    ) |&gt;
    fmt_number(columns = c(Ka, K10, K12, K21), decimals = 3) |&gt;
    fmt_number(columns = Vc, decimals = 1) |&gt;
    fmt_number(columns = c(RMSE, Max_SE_log), decimals = 2) |&gt;
    fmt_number(columns = R2, decimals = 4) |&gt;
    cols_label(.list = c(list(ID = "Subject", Max_SE_log = "Max. SE (log scale)"), html_labels(two_comp_cols))) |&gt;
    cols_align(align = "center", columns = -ID)
}








