Show Code
two_comp_pred &lt;- valid_2c |&gt;
  left_join(dose_by_id, by = "ID") |&gt;
  mutate(pred_data = pmap(list(Ka, K10, K12, K21, Vc, DOSE_mg), \(ka, k10, k12, k21, vc, d) {
    tibble(TIME = time_pred, PRED = two_comp_micro(time_pred, ka, k10, k12, k21, vc, d))
  })) |&gt;
  select(ID, pred_data) |&gt;
  unnest(pred_data)

if (n_converged_2c &gt; 0) {
  bind_rows(
    one_comp_pred |&gt; filter(ID %in% valid_2c$ID) |&gt; mutate(Model = "1-Compartment"),
    two_comp_pred |&gt; mutate(Model = "2-Compartment")
  ) |&gt;
    ggplot() +
    geom_line(aes(x = TIME, y = PRED, color = Model, linetype = Model), linewidth = 1.1) +
    geom_point(data = pk_data |&gt; filter(ID %in% valid_2c$ID), aes(x = TIME, y = CONC), size = 2.8) +
    scale_color_manual(values = c("1-Compartment" = pk_colors[2], "2-Compartment" = pk_colors[3])) +
    facet_wrap(~ ID) +
    labs(
      x = "Time (hours)",
      y = "Concentration (mg/L)",
      title = "One- vs. Two-Compartment Fits",
      subtitle = "Points = observed"
    ) +
    theme(legend.position = "bottom", strip.text = element_text(face = "bold"))
}








